-- PRO3 attendance compatibility tables in the qjhy PostgreSQL database.
-- Rows are intentionally empty on first deployment; DingTalk sync repopulates them.
CREATE TABLE IF NOT EXISTS users (id integer PRIMARY KEY, username text UNIQUE NOT NULL, password text NOT NULL DEFAULT '', name text, role text DEFAULT 'user', status text DEFAULT 'active', permissions text, scopes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), team_id integer, position text, user_role text DEFAULT 'member', dingtalk_user_id text DEFAULT '', points integer DEFAULT 0, biz_type text, dingtalk_userid text, dingtalk_unionid text, is_anchor integer DEFAULT 0, is_attendance_admin integer DEFAULT 0, rest_day text DEFAULT '0', work_start_time text DEFAULT '', work_end_time text DEFAULT '');
CREATE TABLE IF NOT EXISTS teams (id serial PRIMARY KEY, name text NOT NULL, leader_id integer, description text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), biz_type text DEFAULT 'other', dingtalk_dept_id text, is_dingtalk_sync integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS anchors (id serial PRIMARY KEY, name text NOT NULL, nickname text, douyin_id text, uid text, phone text, wechat text, avatar text, lifecycle_status text DEFAULT 'recruiting', recruitment_id integer, account_data_id text, operator_id integer, team_id integer, project text, live_room_id integer, recruit_date text, onboard_date text, training_start_date text, training_end_date text, contract_date text, first_live_date text, trial_end_date text, termination_date text, created_by text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), recruit_type text DEFAULT '线下', game_account text, live_platform text, platform_real_name text, schedule_note text, rest_day text, schedule1 text, schedule2 text, schedule3 text, phone_sim_name text, offline_recruitment_id integer, phone_device text, operator_dingtalk_id text, creator_dingtalk_id text);
CREATE TABLE IF NOT EXISTS dingtalk_users (userid text PRIMARY KEY, unionid text, name text NOT NULL, mobile text, dept_ids text, position text, job_number text, hired_date text, is_leader integer DEFAULT 0, status integer DEFAULT 1, is_bind integer DEFAULT 0, bind_user_id integer, bind_at text, synced_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS dingtalk_departments (dept_id text PRIMARY KEY, name text NOT NULL, parent_id text, is_exclude integer DEFAULT 0, exclude_reason text, synced_at timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS stream_accounts (id serial PRIMARY KEY, name text NOT NULL UNIQUE, sort_order integer DEFAULT 0, created_at timestamptz DEFAULT now(), product_type text DEFAULT '3D捕鱼', is_locked integer DEFAULT 0, dataset_anchor_name text DEFAULT '');
CREATE TABLE IF NOT EXISTS stream_schedules (id serial PRIMARY KEY, date text, account_name text, streamer_name text, role text DEFAULT 'main', start_hour numeric, end_hour numeric, color text, created_at timestamptz DEFAULT now(), gift_amount numeric DEFAULT 0, room_id integer, real_name text DEFAULT '');
CREATE TABLE IF NOT EXISTS business_data (id serial PRIMARY KEY, type text, data_date text, content text, base text);
CREATE TABLE IF NOT EXISTS attendance_records (id serial PRIMARY KEY, dingtalk_userid text NOT NULL, name text NOT NULL, dept_name text DEFAULT '', work_date text NOT NULL, on_duty_time text, off_duty_time text, on_duty_result text, off_duty_result text, on_duty_location text, off_duty_location text, late_minutes integer DEFAULT 0, early_leave_minutes integer DEFAULT 0, work_duration text, absent_days numeric DEFAULT 0, attendance_days numeric DEFAULT 0, rest_days numeric DEFAULT 0, raw_data text, synced_at text, all_check_times text, remark text, remark_by text, remark_at text, verified_by text, verified_at text, UNIQUE(dingtalk_userid, work_date));
CREATE TABLE IF NOT EXISTS approval_instances (id serial PRIMARY KEY, instance_id text NOT NULL UNIQUE, process_code text NOT NULL, approval_type text NOT NULL, title text, originator_userid text NOT NULL, originator_name text, dept_name text, status text NOT NULL, result text, start_time text, end_time text, duration_hours numeric, reason text, leave_type text, form_data text, create_time text, finish_time text, synced_at text);
CREATE TABLE IF NOT EXISTS attendance_sync_log (id serial PRIMARY KEY, sync_date text NOT NULL, total integer DEFAULT 0, synced integer DEFAULT 0, failed integer DEFAULT 0, skipped integer DEFAULT 0, triggered_by text DEFAULT 'cron', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS anchor_attendance_notes (id serial PRIMARY KEY, anchor_name text NOT NULL, note_date text NOT NULL, note_type text DEFAULT 'remark', content text DEFAULT '', created_by text, created_at timestamptz DEFAULT now(), verified_by text, verified_at timestamptz);
CREATE TABLE IF NOT EXISTS anchor_daily_status (id serial PRIMARY KEY, user_id integer NOT NULL, user_name text, date text NOT NULL, status text DEFAULT 'normal', remark text, marked_by text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), approval_status text DEFAULT 'approved', approver_role text DEFAULT '', approved_by text DEFAULT '', approved_at text DEFAULT '', reject_reason text DEFAULT '', UNIQUE(user_id, date));
CREATE INDEX IF NOT EXISTS idx_attendance_records_date ON attendance_records(work_date);
CREATE INDEX IF NOT EXISTS idx_attendance_records_name ON attendance_records(name);
CREATE INDEX IF NOT EXISTS idx_approval_instances_start ON approval_instances(start_time);
CREATE INDEX IF NOT EXISTS idx_anchor_attendance_notes_date ON anchor_attendance_notes(note_date);
-- Seed the compatibility organization view from qjhy's authoritative DingTalk tables.
INSERT INTO dingtalk_users (userid, unionid, name, mobile, dept_ids, position, status)
SELECT user_id, unionid, name, mobile, dept_ids::text, title, CASE WHEN active THEN 1 ELSE 0 END FROM dingtalk_user
ON CONFLICT (userid) DO UPDATE SET name=excluded.name, mobile=excluded.mobile, dept_ids=excluded.dept_ids, position=excluded.position, status=excluded.status;
INSERT INTO dingtalk_departments (dept_id, name, parent_id)
SELECT dept_id, name, parent_id FROM dingtalk_dept
ON CONFLICT (dept_id) DO UPDATE SET name=excluded.name, parent_id=excluded.parent_id;
